\title{Context-aware LLM-based AI Agents for Human-centered Energy Management Systems in Smart Buildings}

















\author[inst1]{Tianzhi He}

\affiliation[inst1]{organization={School of Civil \& Environmental Engineering, and Construction Management, The University of Texas at San Antonio},
            addressline={BSE 1.310, One UTSA Circle}, 
            city={San Antonio},
            postcode={78249}, 
            state={TX},
            country={U.S.}}

\author[inst2]{Farrokh Jazizadeh}
\affiliation[inst2]{organization={Department of Civil and Environmental Engineering, Virginia Polytechnic Institute and State University},
            addressline={200 Patton Hall, 750 Drillfield}, 
            city={Blacksburg},
